/**
 * @file ExportView.tsx
 * @brief 03 / Export - request snapshot or review package of the saved study
 * @author Lukas (Viridis) Dubsik
 * @version 0.1
 *
 * Detailed description:
 *  Only saved data are exported. With unsaved changes the user either
 *  saves first, or exports the last saved snapshot on purpose.
 *  The preview is generated by the service and the download is exactly
 *  the file described in it.
 */
import { useWorkspace } from "../../app/WorkspaceProvider";
import {
  collections,
  dirty,
  revision,
  unapplied,
  unresolvedCount,
} from "../../app/selectors";
import type { ExportPreview } from "../../shared/types";
import "./ExportView.css";

/* Values */
type ExportKind = "request" | "review";
const KINDS: ExportKind[] = ["request", "review"];

// Title and description of each kind of export
const KIND_TEXT: Record<ExportKind, { title: string; text: string }> = {
  request: {
    title: "Request file",
    text: "One revision with its targets, ready to be analysed.",
  },
  review: {
    title: "Review / evidence package",
    text: "The chosen collections and decisions, with the original evidence files.",
  },
};

/* Helper functions */
function previewTitle(preview: ExportPreview): string {
  if (preview.review_status === "draft") return "Draft review";
  if (preview.kind === "request") return "Request file";
  return "Review complete";
}

/* Components */
/**
 * @brief Choice of the export kind and of the collections
 */
function ExportOptions() {
  const { state, dispatch } = useWorkspace();
  const items = collections(state);

  function toggle(collectionId: string, checked: boolean) {
    const selected = checked
      ? [...state.selectedCollections, collectionId]
      : state.selectedCollections.filter((id) => id !== collectionId);
    dispatch({
      type: "patch",
      value: { selectedCollections: selected, exportPreview: null },
    });
  }

  return (
    <>
      <div className="export-options">
        {KINDS.map((kind) => (
          <label
            key={kind}
            className={`export-option ${state.exportKind === kind ? "selected" : ""}`}
          >
            <input
              type="radio"
              name="export-kind"
              checked={state.exportKind === kind}
              onChange={() =>
                dispatch({
                  type: "patch",
                  value: { exportKind: kind, exportPreview: null },
                })
              }
            />
            <span>
              <strong>{KIND_TEXT[kind].title}</strong>
              <small>{KIND_TEXT[kind].text}</small>
            </span>
            <span className="mono">.{kind}.json</span>
          </label>
        ))}
      </div>
      {state.exportKind === "review" && (
        <fieldset>
          <legend>Collections for this revision</legend>
          {!items.length && (
            <p className="hint">
              Import evidence and create a review collection first.
            </p>
          )}
          {items.map((item) => (
            <label className="checkbox" key={item.collection_id}>
              <input
                type="checkbox"
                checked={state.selectedCollections.includes(item.collection_id)}
                onChange={(event) =>
                  toggle(item.collection_id, event.target.checked)
                }
              />
              <span>
                {item.name}
                <small>
                  {item.memberships.length} members · {unresolvedCount([item])}{" "}
                  unresolved
                </small>
              </span>
            </label>
          ))}
        </fieldset>
      )}
    </>
  );
}

/**
 * @brief Frozen description of the prepared file with its download link
 */
function PreviewPanel(props: { preview: ExportPreview }) {
  const { preview } = props;
  const draft = preview.review_status === "draft";

  // Numbers shown in the grid
  const stats = [
    [preview.target_count, "Targets"],
    [preview.candidate_count, "Source candidates"],
    [preview.collection_count, "Collections"],
    [preview.unresolved_count, "Unresolved"],
    [preview.dependency_count, "External dependencies"],
  ] as const;

  return (
    <section className="panel export-preview" aria-label="Export preview">
      <div className="panel-heading">
        <div>
          <p className="eyebrow">From the saved study</p>
          <h2>{previewTitle(preview)}</h2>
        </div>
        <span className={`badge ${draft ? "amber" : "teal"}`}>
          {preview.review_status ?? "Request"}
        </span>
      </div>
      <div className="stat-grid">
        {stats.map(([value, label]) => (
          <div key={label}>
            <strong>{value}</strong>
            <span>{label}</span>
          </div>
        ))}
      </div>
      <p>
        {preview.kind === "review"
          ? "The original evidence files are included unchanged. External files they refer to are only listed, not downloaded."
          : "This is a plain JSON request, not an IRCOMP YAML specification (yet)."}
      </p>
      {preview.review_status === "reviewed" && (
        <p className="notice">Every decision has a reason now.</p>
      )}
      <dl className="metadata">
        <div>
          <dt>Filename</dt>
          <dd className="mono">{preview.filename}</dd>
        </div>
        <div>
          <dt>Saved version / revision</dt>
          <dd>
            {preview.saved_version} /{" "}
            <span className="mono">{preview.revision_id}</span>
          </dd>
        </div>
        <div>
          <dt>SHA-256</dt>
          <dd className="mono">{preview.sha256}</dd>
        </div>
        <div>
          <dt>Size</dt>
          <dd>{preview.byte_length.toLocaleString()} bytes</dd>
        </div>
      </dl>
      <a
        className="button"
        download
        href={`/api/v1/exports/${preview.export_id}/file`}
      >
        {draft ? "Download draft review" : "Download snapshot"}
      </a>
    </section>
  );
}

/* View */
export function ExportView() {
  const { state, controller } = useWorkspace();
  const workspace = state.workspace!;
  const context = revision(state)!;
  const selected = collections(state).filter((item) =>
    state.selectedCollections.includes(item.collection_id),
  );

  const unsaved = dirty(state);
  const drafts = unapplied(state);
  const neverSaved = !workspace.base_saved_version;
  // A review needs at least one collection
  const missingCollections = state.exportKind === "review" && !selected.length;

  return (
    <>
      <div className="section-intro">
        <div>
          <p className="eyebrow">03 / Export</p>
          <h1>Export the study</h1>
          <p>Check what goes into the file before downloading it.</p>
        </div>
      </div>
      <div className="export-grid">
        <section className="panel">
          <div className="panel-heading">
            <h2>What to export</h2>
          </div>
          <ExportOptions />
          {neverSaved && (
            <p className="notice">
              Save the study first, only saved data can be exported.
            </p>
          )}
          {unsaved && (
            <p className="notice">
              There are unsaved changes. Save first, or use Export last saved
              (it won't contain the newer changes).
            </p>
          )}
          {drafts && (
            <p className="notice">
              Edits which aren't applied are never exported. Apply them first if
              you want them in.
            </p>
          )}
          <div className="actions wrap">
            <button
              disabled={
                state.busy ||
                neverSaved ||
                unsaved ||
                drafts ||
                missingCollections
              }
              onClick={() => void controller.previewExport(false)}
            >
              Preview saved export
            </button>
            {(unsaved || drafts) && (
              <button
                className="secondary"
                disabled={state.busy || neverSaved || missingCollections}
                onClick={() => void controller.previewExport(true)}
              >
                Export last saved
              </button>
            )}
          </div>
        </section>
        <aside className="panel">
          <div className="panel-heading">
            <h2>Exported from</h2>
          </div>
          <dl className="metadata">
            <div>
              <dt>Saved version</dt>
              <dd>{workspace.base_saved_version || "Not saved"}</dd>
            </div>
            <div>
              <dt>Request revision</dt>
              <dd className="mono">{context.revision_id}</dd>
            </div>
            <div>
              <dt>Reference</dt>
              <dd>{context.reference_id}</dd>
            </div>
            <div>
              <dt>Targets (open study)</dt>
              <dd>{context.targets.length}</dd>
            </div>
            <div>
              <dt>Selected collections</dt>
              <dd>{selected.length}</dd>
            </div>
          </dl>
          <p className="hint">
            The preview below shows exactly what the downloaded file contains.
          </p>
        </aside>
      </div>
      {state.exportPreview && <PreviewPanel preview={state.exportPreview} />}
    </>
  );
}
